export async function listTools() {
  return [
    {
      name: 'text_transform',
      description: 'Transform text: uppercase, lowercase, or slug.',
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'The text to transform.' },
          mode: { type: 'string', enum: ['uppercase', 'lowercase', 'slug'], description: 'Transform mode.' },
          trim: { type: 'boolean', default: true, description: 'Whether to trim surrounding whitespace. Defaults to true.' }
        },
        required: ['text', 'mode'],
        additionalProperties: false
      }
    }
  ];
}

function validateArgs(args) {
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }
  const allowed = new Set(['text', 'mode', 'trim']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }
  if (typeof args.text !== 'string') {
    throw new Error('text must be a string');
  }
  const validModes = ['uppercase', 'lowercase', 'slug'];
  if (!validModes.includes(args.mode)) {
    throw new Error('mode must be one of: uppercase, lowercase, slug');
  }
  if ('trim' in args && typeof args.trim !== 'boolean') {
    throw new Error('trim must be a boolean');
  }
}

export async function callTool(name, args = {}) {
  if (name !== 'text_transform') {
    throw new Error(`Unknown tool: ${name}`);
  }
  validateArgs(args);
  const text = args.text;
  const mode = args.mode;
  const trim = args.trim !== undefined ? args.trim : true;
  let result;
  if (mode === 'uppercase') {
    result = trim ? text.toUpperCase().trim() : text.toUpperCase();
  } else if (mode === 'lowercase') {
    result = trim ? text.toLowerCase().trim() : text.toLowerCase();
  } else if (mode === 'slug') {
    let s = text.toLowerCase();
    if (trim) s = s.trim();
    s = s.replace(/[^a-z0-9]+/g, '-');
    s = s.replace(/^-+|-+$/g, '');
    result = s;
  }
  return { content: [{ type: 'text', text: result }] };
}
